catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        return;
    }
    var cert_type = g_form.getValue('globalsign_mssl_certificate_type');
    var ca_policy = g_form.getValue('ca_policy_details');

    try {
        var policyData = JSON.parse(ca_policy);
    } catch (e) {
        throw("Invalid JSON in ca_policy_details:", e);
    }

    // Clear existing options before adding new ones
    g_form.clearOptions('hash_function');

    for (var i = 0; i < policyData.length; i++) {
        var caSettings = policyData[i].caSettings || [];
        for (var s = 0; s < caSettings.length; s++) {
            var certTypes = caSettings[s].certTypes || [];
            for (var c = 0; c < certTypes.length; c++) {
                var certTypeObj = certTypes[c];
                if (certTypeObj.name === cert_type) {
                    var shaTypes = certTypeObj.shaType || [];
                    for (var j = 0; j < shaTypes.length; j++) {
                        g_form.addOption('hash_function', shaTypes[j], shaTypes[j]);
                    }
                    // Set default value (first one)
                    if (shaTypes.length > 0) {
                        g_form.setValue('hash_function', shaTypes[0]);
                    }
                    return; 
                }
            }
        }
    }
}
